window.MG_LAZY_DATA["data/lazy/courses/v11-intel-tunnel-falls-8cf472594158a048.json"]={sha256:"8cf472594158a048d68c72f483d9c0932d1d9c275b9b7d33568ce2d1aeeb6327",value:{"id":"v11-intel-tunnel-falls","title":"Intel Tunnel Falls 矽自旋研究晶片","titleEn":"Intel Tunnel Falls silicon-spin research chip","category":"computing","subcategory":"quantum-spin","subcategoryTitle":"半導體自旋量子系統","subcategoryTitleEn":"Semiconductor-spin quantum systems","learningTrack":"quantum","learningSubdiscipline":"quantum-spin","learningTags":["quantum","quantum-spin","intel-tunnel-falls"],"kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"stages":[{"id":"v11-intel-tunnel-falls-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在Intel Tunnel Falls 矽自旋研究晶片案例中比較閘定義量子點與鄰點交換，各完成分析及驗證。","descriptionEn":"Analyze and validate gate-defined dots and neighbor exchange within the Intel Tunnel Falls silicon-spin research chip case.","steps":[{"id":"v11-intel-tunnel-falls-v11-01","order":1,"sequence":1,"title":"量子點與自旋子空間：架構分析","titleEn":"Quantum dots and spin subspaces: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":[],"objective":"針對閘定義量子點提出可反駁的量子點與自旋子空間模型與驗證紀錄。","objectiveEn":"Produce a falsifiable quantum dots and spin subspaces model and evidence record for gate-defined dots.","instruction":"在「Intel Tunnel Falls 矽自旋研究晶片」的師傅示意與公開來源中，先辨識閘定義量子點。閘定義侷限與電荷狀態；電子自旋提供與電荷位置不同的位元自由度。 建立量子點與自旋子空間的輸入、狀態、輸出及邊界圖；本課重點是量子點、交換、自旋讀出與晶圓變異。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。分開電荷穩定圖與自旋態能階圖。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify gate-defined dots in the mentor diagram and primary sources for Intel Tunnel Falls silicon-spin research chip. Gates define confinement/charge; electron spin supplies a degree of freedom distinct from position. Draw the inputs, states, outputs and boundaries of quantum dots and spin subspaces, focusing on quantum dots, exchange, spin readout and wafer variability. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate a charge stability diagram from spin levels. Record units, undisclosed parameters and model breakdown conditions.","observation":"分開電荷穩定圖與自旋態能階圖。","observationEn":"Separate a charge stability diagram from spin levels.","failure":"常見誤判：能看到量子點就已證明自旋閘與讀出。","failureEn":"Common misconception: Observing a quantum dot proves spin gates and readout.","check":"提交閘定義量子點的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for gate-defined dots.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-01-k1","title":"量子點與自旋子空間","titleEn":"Quantum dots and spin subspaces","text":"閘定義侷限與電荷狀態；電子自旋提供與電荷位置不同的位元自由度。 本課架構對應：閘定義量子點","textEn":"Gates define confinement/charge; electron spin supplies a degree of freedom distinct from position. Course architecture correspondence: Gate-defined dots","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開電荷穩定圖與自旋態能階圖。 應逐項保留基準與不確定度；能看到量子點就已證明自旋閘與讀出。 是本單元要排除的誤解。","textEn":"Separate a charge stability diagram from spin levels. Retain each reference and uncertainty; reject the misconception: Observing a quantum dot proves spin gates and readout.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 57 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^57=0.939193。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 57 independent events with equal p=0.0011: no-error probability (1−p)^57=0.939193. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就閘定義量子點的「量子點與自旋子空間」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for quantum dots and spin subspaces in gate-defined dots?","options":["閘定義侷限與電荷狀態；電子自旋提供與電荷位置不同的位元自由度。","能看到量子點就已證明自旋閘與讀出。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Gates define confinement/charge; electron spin supplies a degree of freedom distinct from position.","Observing a quantum dot proves spin gates and readout.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"閘定義侷限與電荷狀態；電子自旋提供與電荷位置不同的位元自由度。 分開電荷穩定圖與自旋態能階圖。","explanationEn":"Gates define confinement/charge; electron spin supplies a degree of freedom distinct from position. Separate a charge stability diagram from spin levels."}},{"id":"v11-intel-tunnel-falls-v11-02","order":2,"sequence":2,"title":"量子點與自旋子空間：證據驗證","titleEn":"Quantum dots and spin subspaces: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-01"],"objective":"針對閘定義量子點提出可反駁的量子點與自旋子空間模型與驗證紀錄。","objectiveEn":"Produce a falsifiable quantum dots and spin subspaces model and evidence record for gate-defined dots.","instruction":"沿用前一步「量子點與自旋子空間」模型，檢查閘定義量子點的兩個假想案例。分開電荷穩定圖與自旋態能階圖。 先訂可接受誤差，再比較預測與獨立計算；區分閘定義侷限與電荷狀態；電子自旋提供與電荷位置不同的位元自由度。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous quantum dots and spin subspaces model to inspect two hypothetical cases involving gate-defined dots. Separate a charge stability diagram from spin levels. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Gates define confinement/charge; electron spin supplies a degree of freedom distinct from position.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"分開電荷穩定圖與自旋態能階圖。","observationEn":"Separate a charge stability diagram from spin levels.","failure":"常見誤判：能看到量子點就已證明自旋閘與讀出。","failureEn":"Common misconception: Observing a quantum dot proves spin gates and readout.","check":"提交閘定義量子點的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for gate-defined dots.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-02-k1","title":"量子點與自旋子空間","titleEn":"Quantum dots and spin subspaces","text":"閘定義侷限與電荷狀態；電子自旋提供與電荷位置不同的位元自由度。 本課架構對應：閘定義量子點","textEn":"Gates define confinement/charge; electron spin supplies a degree of freedom distinct from position. Course architecture correspondence: Gate-defined dots","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開電荷穩定圖與自旋態能階圖。 應逐項保留基準與不確定度；能看到量子點就已證明自旋閘與讀出。 是本單元要排除的誤解。","textEn":"Separate a charge stability diagram from spin levels. Retain each reference and uncertainty; reject the misconception: Observing a quantum dot proves spin gates and readout.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 57 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^57=0.939193。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 57 independent events with equal p=0.0011: no-error probability (1−p)^57=0.939193. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就閘定義量子點的「量子點與自旋子空間」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for quantum dots and spin subspaces in gate-defined dots?","options":["能看到量子點就已證明自旋閘與讀出。","分開電荷穩定圖與自旋態能階圖。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Observing a quantum dot proves spin gates and readout.","Separate a charge stability diagram from spin levels.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"閘定義侷限與電荷狀態；電子自旋提供與電荷位置不同的位元自由度。 分開電荷穩定圖與自旋態能階圖。","explanationEn":"Gates define confinement/charge; electron spin supplies a degree of freedom distinct from position. Separate a charge stability diagram from spin levels."}},{"id":"v11-intel-tunnel-falls-v11-03","order":3,"sequence":3,"title":"交換相互作用：架構分析","titleEn":"Exchange interactions: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-02"],"objective":"針對鄰點交換提出可反駁的交換相互作用模型與驗證紀錄。","objectiveEn":"Produce a falsifiable exchange interactions model and evidence record for neighbor exchange.","instruction":"在「Intel Tunnel Falls 矽自旋研究晶片」的師傅示意與公開來源中，先辨識鄰點交換。鄰近電子的波函數重疊調節交換；電荷雜訊可能映射為閘誤差。 建立交換相互作用的輸入、狀態、輸出及邊界圖；本課重點是量子點、交換、自旋讀出與晶圓變異。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。對假想 J 參數做靈敏度與噪聲傳播。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify neighbor exchange in the mentor diagram and primary sources for Intel Tunnel Falls silicon-spin research chip. Wavefunction overlap controls exchange; charge noise can become gate error. Draw the inputs, states, outputs and boundaries of exchange interactions, focusing on quantum dots, exchange, spin readout and wafer variability. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Propagate assumed J sensitivity and noise. Record units, undisclosed parameters and model breakdown conditions.","observation":"對假想 J 參數做靈敏度與噪聲傳播。","observationEn":"Propagate assumed J sensitivity and noise.","failure":"常見誤判：縮小點間距一定改善所有誤差。","failureEn":"Common misconception: Reducing dot spacing improves every error source.","check":"提交鄰點交換的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for neighbor exchange.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-03-k1","title":"交換相互作用","titleEn":"Exchange interactions","text":"鄰近電子的波函數重疊調節交換；電荷雜訊可能映射為閘誤差。 本課架構對應：鄰點交換","textEn":"Wavefunction overlap controls exchange; charge noise can become gate error. Course architecture correspondence: Neighbor exchange","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"對假想 J 參數做靈敏度與噪聲傳播。 應逐項保留基準與不確定度；縮小點間距一定改善所有誤差。 是本單元要排除的誤解。","textEn":"Propagate assumed J sensitivity and noise. Retain each reference and uncertainty; reject the misconception: Reducing dot spacing improves every error source.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]}],"quiz":{"question":"就鄰點交換的「交換相互作用」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for exchange interactions in neighbor exchange?","options":["縮小點間距一定改善所有誤差。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","鄰近電子的波函數重疊調節交換；電荷雜訊可能映射為閘誤差。"],"optionsEn":["Reducing dot spacing improves every error source.","Equal case averages rule out spatial, temporal and model errors.","Wavefunction overlap controls exchange; charge noise can become gate error."],"answer":2,"explanation":"鄰近電子的波函數重疊調節交換；電荷雜訊可能映射為閘誤差。 對假想 J 參數做靈敏度與噪聲傳播。","explanationEn":"Wavefunction overlap controls exchange; charge noise can become gate error. Propagate assumed J sensitivity and noise."}},{"id":"v11-intel-tunnel-falls-v11-04","order":4,"sequence":4,"title":"交換相互作用：證據驗證","titleEn":"Exchange interactions: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-03"],"objective":"針對鄰點交換提出可反駁的交換相互作用模型與驗證紀錄。","objectiveEn":"Produce a falsifiable exchange interactions model and evidence record for neighbor exchange.","instruction":"沿用前一步「交換相互作用」模型，檢查鄰點交換的兩個假想案例。對假想 J 參數做靈敏度與噪聲傳播。 先訂可接受誤差，再比較預測與獨立計算；區分鄰近電子的波函數重疊調節交換；電荷雜訊可能映射為閘誤差。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous exchange interactions model to inspect two hypothetical cases involving neighbor exchange. Propagate assumed J sensitivity and noise. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Wavefunction overlap controls exchange; charge noise can become gate error.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"對假想 J 參數做靈敏度與噪聲傳播。","observationEn":"Propagate assumed J sensitivity and noise.","failure":"常見誤判：縮小點間距一定改善所有誤差。","failureEn":"Common misconception: Reducing dot spacing improves every error source.","check":"提交鄰點交換的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for neighbor exchange.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-04-k1","title":"交換相互作用","titleEn":"Exchange interactions","text":"鄰近電子的波函數重疊調節交換；電荷雜訊可能映射為閘誤差。 本課架構對應：鄰點交換","textEn":"Wavefunction overlap controls exchange; charge noise can become gate error. Course architecture correspondence: Neighbor exchange","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"對假想 J 參數做靈敏度與噪聲傳播。 應逐項保留基準與不確定度；縮小點間距一定改善所有誤差。 是本單元要排除的誤解。","textEn":"Propagate assumed J sensitivity and noise. Retain each reference and uncertainty; reject the misconception: Reducing dot spacing improves every error source.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]}],"quiz":{"question":"就鄰點交換的「交換相互作用」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for exchange interactions in neighbor exchange?","options":["對假想 J 參數做靈敏度與噪聲傳播。","縮小點間距一定改善所有誤差。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Propagate assumed J sensitivity and noise.","Reducing dot spacing improves every error source.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"鄰近電子的波函數重疊調節交換；電荷雜訊可能映射為閘誤差。 對假想 J 參數做靈敏度與噪聲傳播。","explanationEn":"Wavefunction overlap controls exchange; charge noise can become gate error. Propagate assumed J sensitivity and noise."}}]},{"id":"v11-intel-tunnel-falls-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在Intel Tunnel Falls 矽自旋研究晶片案例中比較自旋共振選擇與自旋轉電荷讀出，各完成分析及驗證。","descriptionEn":"Analyze and validate spin-resonance selectivity and spin-to-charge readout within the Intel Tunnel Falls silicon-spin research chip case.","steps":[{"id":"v11-intel-tunnel-falls-v11-05","order":1,"sequence":5,"title":"自旋控制與共振：架構分析","titleEn":"Spin control and resonance: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-04"],"objective":"針對自旋共振選擇提出可反駁的自旋控制與共振模型與驗證紀錄。","objectiveEn":"Produce a falsifiable spin control and resonance model and evidence record for spin-resonance selectivity.","instruction":"在「Intel Tunnel Falls 矽自旋研究晶片」的師傅示意與公開來源中，先辨識自旋共振選擇。能階分裂設定共振尺度；控制選擇性仍受漂移與鄰近頻率限制。 建立自旋控制與共振的輸入、狀態、輸出及邊界圖；本課重點是量子點、交換、自旋讀出與晶圓變異。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較兩個假想頻率分佈的可分辨性。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify spin-resonance selectivity in the mentor diagram and primary sources for Intel Tunnel Falls silicon-spin research chip. Splitting defines resonance scales; drift and neighboring frequencies limit selectivity. Draw the inputs, states, outputs and boundaries of spin control and resonance, focusing on quantum dots, exchange, spin readout and wafer variability. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare resolvability of two assumed frequency distributions. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較兩個假想頻率分佈的可分辨性。","observationEn":"Compare resolvability of two assumed frequency distributions.","failure":"常見誤判：相同半導體材料代表完全相同共振頻率。","failureEn":"Common misconception: Identical semiconductor material means identical resonance frequency.","check":"提交自旋共振選擇的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for spin-resonance selectivity.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-05-k1","title":"自旋控制與共振","titleEn":"Spin control and resonance","text":"能階分裂設定共振尺度；控制選擇性仍受漂移與鄰近頻率限制。 本課架構對應：自旋共振選擇","textEn":"Splitting defines resonance scales; drift and neighboring frequencies limit selectivity. Course architecture correspondence: Spin-resonance selectivity","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較兩個假想頻率分佈的可分辨性。 應逐項保留基準與不確定度；相同半導體材料代表完全相同共振頻率。 是本單元要排除的誤解。","textEn":"Compare resolvability of two assumed frequency distributions. Retain each reference and uncertainty; reject the misconception: Identical semiconductor material means identical resonance frequency.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]}],"quiz":{"question":"就自旋共振選擇的「自旋控制與共振」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for spin control and resonance in spin-resonance selectivity?","options":["相同半導體材料代表完全相同共振頻率。","能階分裂設定共振尺度；控制選擇性仍受漂移與鄰近頻率限制。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Identical semiconductor material means identical resonance frequency.","Splitting defines resonance scales; drift and neighboring frequencies limit selectivity.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"能階分裂設定共振尺度；控制選擇性仍受漂移與鄰近頻率限制。 比較兩個假想頻率分佈的可分辨性。","explanationEn":"Splitting defines resonance scales; drift and neighboring frequencies limit selectivity. Compare resolvability of two assumed frequency distributions."}},{"id":"v11-intel-tunnel-falls-v11-06","order":2,"sequence":6,"title":"自旋控制與共振：證據驗證","titleEn":"Spin control and resonance: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-05"],"objective":"針對自旋共振選擇提出可反駁的自旋控制與共振模型與驗證紀錄。","objectiveEn":"Produce a falsifiable spin control and resonance model and evidence record for spin-resonance selectivity.","instruction":"沿用前一步「自旋控制與共振」模型，檢查自旋共振選擇的兩個假想案例。比較兩個假想頻率分佈的可分辨性。 先訂可接受誤差，再比較預測與獨立計算；區分能階分裂設定共振尺度；控制選擇性仍受漂移與鄰近頻率限制。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous spin control and resonance model to inspect two hypothetical cases involving spin-resonance selectivity. Compare resolvability of two assumed frequency distributions. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Splitting defines resonance scales; drift and neighboring frequencies limit selectivity.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較兩個假想頻率分佈的可分辨性。","observationEn":"Compare resolvability of two assumed frequency distributions.","failure":"常見誤判：相同半導體材料代表完全相同共振頻率。","failureEn":"Common misconception: Identical semiconductor material means identical resonance frequency.","check":"提交自旋共振選擇的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for spin-resonance selectivity.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-06-k1","title":"自旋控制與共振","titleEn":"Spin control and resonance","text":"能階分裂設定共振尺度；控制選擇性仍受漂移與鄰近頻率限制。 本課架構對應：自旋共振選擇","textEn":"Splitting defines resonance scales; drift and neighboring frequencies limit selectivity. Course architecture correspondence: Spin-resonance selectivity","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較兩個假想頻率分佈的可分辨性。 應逐項保留基準與不確定度；相同半導體材料代表完全相同共振頻率。 是本單元要排除的誤解。","textEn":"Compare resolvability of two assumed frequency distributions. Retain each reference and uncertainty; reject the misconception: Identical semiconductor material means identical resonance frequency.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]}],"quiz":{"question":"就自旋共振選擇的「自旋控制與共振」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for spin control and resonance in spin-resonance selectivity?","options":["相同半導體材料代表完全相同共振頻率。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較兩個假想頻率分佈的可分辨性。"],"optionsEn":["Identical semiconductor material means identical resonance frequency.","Equal case averages rule out spatial, temporal and model errors.","Compare resolvability of two assumed frequency distributions."],"answer":2,"explanation":"能階分裂設定共振尺度；控制選擇性仍受漂移與鄰近頻率限制。 比較兩個假想頻率分佈的可分辨性。","explanationEn":"Splitting defines resonance scales; drift and neighboring frequencies limit selectivity. Compare resolvability of two assumed frequency distributions."}},{"id":"v11-intel-tunnel-falls-v11-07","order":3,"sequence":7,"title":"自旋轉電荷讀出：架構分析","titleEn":"Spin-to-charge readout: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-06"],"objective":"針對自旋轉電荷讀出提出可反駁的自旋轉電荷讀出模型與驗證紀錄。","objectiveEn":"Produce a falsifiable spin-to-charge readout model and evidence record for spin-to-charge readout.","instruction":"在「Intel Tunnel Falls 矽自旋研究晶片」的師傅示意與公開來源中，先辨識自旋轉電荷讀出。某些讀出先把自旋資訊轉成可感測的電荷事件，需分開轉換與感測錯誤。 建立自旋轉電荷讀出的輸入、狀態、輸出及邊界圖；本課重點是量子點、交換、自旋讀出與晶圓變異。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。建立兩層混淆模型並與單層近似比較。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify spin-to-charge readout in the mentor diagram and primary sources for Intel Tunnel Falls silicon-spin research chip. Some readout maps spin information to charge events, requiring separate conversion and sensing error budgets. Draw the inputs, states, outputs and boundaries of spin-to-charge readout, focusing on quantum dots, exchange, spin readout and wafer variability. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare a two-layer confusion model with a one-layer approximation. Record units, undisclosed parameters and model breakdown conditions.","observation":"建立兩層混淆模型並與單層近似比較。","observationEn":"Compare a two-layer confusion model with a one-layer approximation.","failure":"常見誤判：電荷感測精度單獨等於自旋讀出精度。","failureEn":"Common misconception: Charge-sensing accuracy alone equals spin-readout accuracy.","check":"提交自旋轉電荷讀出的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for spin-to-charge readout.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-07-k1","title":"自旋轉電荷讀出","titleEn":"Spin-to-charge readout","text":"某些讀出先把自旋資訊轉成可感測的電荷事件，需分開轉換與感測錯誤。 本課架構對應：自旋轉電荷讀出","textEn":"Some readout maps spin information to charge events, requiring separate conversion and sensing error budgets. Course architecture correspondence: Spin-to-charge readout","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"建立兩層混淆模型並與單層近似比較。 應逐項保留基準與不確定度；電荷感測精度單獨等於自旋讀出精度。 是本單元要排除的誤解。","textEn":"Compare a two-layer confusion model with a one-layer approximation. Retain each reference and uncertainty; reject the misconception: Charge-sensing accuracy alone equals spin-readout accuracy.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]}],"quiz":{"question":"就自旋轉電荷讀出的「自旋轉電荷讀出」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for spin-to-charge readout in spin-to-charge readout?","options":["某些讀出先把自旋資訊轉成可感測的電荷事件，需分開轉換與感測錯誤。","電荷感測精度單獨等於自旋讀出精度。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Some readout maps spin information to charge events, requiring separate conversion and sensing error budgets.","Charge-sensing accuracy alone equals spin-readout accuracy.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"某些讀出先把自旋資訊轉成可感測的電荷事件，需分開轉換與感測錯誤。 建立兩層混淆模型並與單層近似比較。","explanationEn":"Some readout maps spin information to charge events, requiring separate conversion and sensing error budgets. Compare a two-layer confusion model with a one-layer approximation."}},{"id":"v11-intel-tunnel-falls-v11-08","order":4,"sequence":8,"title":"自旋轉電荷讀出：證據驗證","titleEn":"Spin-to-charge readout: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-07"],"objective":"針對自旋轉電荷讀出提出可反駁的自旋轉電荷讀出模型與驗證紀錄。","objectiveEn":"Produce a falsifiable spin-to-charge readout model and evidence record for spin-to-charge readout.","instruction":"沿用前一步「自旋轉電荷讀出」模型，檢查自旋轉電荷讀出的兩個假想案例。建立兩層混淆模型並與單層近似比較。 先訂可接受誤差，再比較預測與獨立計算；區分某些讀出先把自旋資訊轉成可感測的電荷事件，需分開轉換與感測錯誤。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous spin-to-charge readout model to inspect two hypothetical cases involving spin-to-charge readout. Compare a two-layer confusion model with a one-layer approximation. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Some readout maps spin information to charge events, requiring separate conversion and sensing error budgets.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"建立兩層混淆模型並與單層近似比較。","observationEn":"Compare a two-layer confusion model with a one-layer approximation.","failure":"常見誤判：電荷感測精度單獨等於自旋讀出精度。","failureEn":"Common misconception: Charge-sensing accuracy alone equals spin-readout accuracy.","check":"提交自旋轉電荷讀出的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for spin-to-charge readout.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-08-k1","title":"自旋轉電荷讀出","titleEn":"Spin-to-charge readout","text":"某些讀出先把自旋資訊轉成可感測的電荷事件，需分開轉換與感測錯誤。 本課架構對應：自旋轉電荷讀出","textEn":"Some readout maps spin information to charge events, requiring separate conversion and sensing error budgets. Course architecture correspondence: Spin-to-charge readout","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"建立兩層混淆模型並與單層近似比較。 應逐項保留基準與不確定度；電荷感測精度單獨等於自旋讀出精度。 是本單元要排除的誤解。","textEn":"Compare a two-layer confusion model with a one-layer approximation. Retain each reference and uncertainty; reject the misconception: Charge-sensing accuracy alone equals spin-readout accuracy.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]}],"quiz":{"question":"就自旋轉電荷讀出的「自旋轉電荷讀出」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for spin-to-charge readout in spin-to-charge readout?","options":["電荷感測精度單獨等於自旋讀出精度。","建立兩層混淆模型並與單層近似比較。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Charge-sensing accuracy alone equals spin-readout accuracy.","Compare a two-layer confusion model with a one-layer approximation.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"某些讀出先把自旋資訊轉成可感測的電荷事件，需分開轉換與感測錯誤。 建立兩層混淆模型並與單層近似比較。","explanationEn":"Some readout maps spin information to charge events, requiring separate conversion and sensing error budgets. Compare a two-layer confusion model with a one-layer approximation."}}]},{"id":"v11-intel-tunnel-falls-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在Intel Tunnel Falls 矽自旋研究晶片案例中比較跨點參數變異與低溫控制熱預算，各完成分析及驗證。","descriptionEn":"Analyze and validate across-dot variability and cryogenic-controller heat budget within the Intel Tunnel Falls silicon-spin research chip case.","steps":[{"id":"v11-intel-tunnel-falls-v11-09","order":1,"sequence":9,"title":"晶圓變異與可擴充性：架構分析","titleEn":"Wafer variability and scaling: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-08"],"objective":"針對跨點參數變異提出可反駁的晶圓變異與可擴充性模型與驗證紀錄。","objectiveEn":"Produce a falsifiable wafer variability and scaling model and evidence record for across-dot variability.","instruction":"在「Intel Tunnel Falls 矽自旋研究晶片」的師傅示意與公開來源中，先辨識跨點參數變異。製程相容性支援多顆元件，但均勻性、接線及校正依然限制擴充。 建立晶圓變異與可擴充性的輸入、狀態、輸出及邊界圖；本課重點是量子點、交換、自旋讀出與晶圓變異。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較跨假想元件參數分佈而非只取最佳點。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify across-dot variability in the mentor diagram and primary sources for Intel Tunnel Falls silicon-spin research chip. Process compatibility supports many devices while uniformity, wiring and calibration still limit scaling. Draw the inputs, states, outputs and boundaries of wafer variability and scaling, focusing on quantum dots, exchange, spin readout and wafer variability. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare assumed device distributions rather than one best point. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較跨假想元件參數分佈而非只取最佳點。","observationEn":"Compare assumed device distributions rather than one best point.","failure":"常見誤判：CMOS 相容即表示所有位元均已容錯。","failureEn":"Common misconception: CMOS compatibility means all qubits are already fault-tolerant.","check":"提交跨點參數變異的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for across-dot variability.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-09-k1","title":"晶圓變異與可擴充性","titleEn":"Wafer variability and scaling","text":"製程相容性支援多顆元件，但均勻性、接線及校正依然限制擴充。 本課架構對應：跨點參數變異","textEn":"Process compatibility supports many devices while uniformity, wiring and calibration still limit scaling. Course architecture correspondence: Across-dot variability","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較跨假想元件參數分佈而非只取最佳點。 應逐項保留基準與不確定度；CMOS 相容即表示所有位元均已容錯。 是本單元要排除的誤解。","textEn":"Compare assumed device distributions rather than one best point. Retain each reference and uncertainty; reject the misconception: CMOS compatibility means all qubits are already fault-tolerant.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]}],"quiz":{"question":"就跨點參數變異的「晶圓變異與可擴充性」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for wafer variability and scaling in across-dot variability?","options":["CMOS 相容即表示所有位元均已容錯。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","製程相容性支援多顆元件，但均勻性、接線及校正依然限制擴充。"],"optionsEn":["CMOS compatibility means all qubits are already fault-tolerant.","Equal case averages rule out spatial, temporal and model errors.","Process compatibility supports many devices while uniformity, wiring and calibration still limit scaling."],"answer":2,"explanation":"製程相容性支援多顆元件，但均勻性、接線及校正依然限制擴充。 比較跨假想元件參數分佈而非只取最佳點。","explanationEn":"Process compatibility supports many devices while uniformity, wiring and calibration still limit scaling. Compare assumed device distributions rather than one best point."}},{"id":"v11-intel-tunnel-falls-v11-10","order":2,"sequence":10,"title":"晶圓變異與可擴充性：證據驗證","titleEn":"Wafer variability and scaling: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-09"],"objective":"針對跨點參數變異提出可反駁的晶圓變異與可擴充性模型與驗證紀錄。","objectiveEn":"Produce a falsifiable wafer variability and scaling model and evidence record for across-dot variability.","instruction":"沿用前一步「晶圓變異與可擴充性」模型，檢查跨點參數變異的兩個假想案例。比較跨假想元件參數分佈而非只取最佳點。 先訂可接受誤差，再比較預測與獨立計算；區分製程相容性支援多顆元件，但均勻性、接線及校正依然限制擴充。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous wafer variability and scaling model to inspect two hypothetical cases involving across-dot variability. Compare assumed device distributions rather than one best point. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Process compatibility supports many devices while uniformity, wiring and calibration still limit scaling.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較跨假想元件參數分佈而非只取最佳點。","observationEn":"Compare assumed device distributions rather than one best point.","failure":"常見誤判：CMOS 相容即表示所有位元均已容錯。","failureEn":"Common misconception: CMOS compatibility means all qubits are already fault-tolerant.","check":"提交跨點參數變異的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for across-dot variability.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-10-k1","title":"晶圓變異與可擴充性","titleEn":"Wafer variability and scaling","text":"製程相容性支援多顆元件，但均勻性、接線及校正依然限制擴充。 本課架構對應：跨點參數變異","textEn":"Process compatibility supports many devices while uniformity, wiring and calibration still limit scaling. Course architecture correspondence: Across-dot variability","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較跨假想元件參數分佈而非只取最佳點。 應逐項保留基準與不確定度；CMOS 相容即表示所有位元均已容錯。 是本單元要排除的誤解。","textEn":"Compare assumed device distributions rather than one best point. Retain each reference and uncertainty; reject the misconception: CMOS compatibility means all qubits are already fault-tolerant.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]}],"quiz":{"question":"就跨點參數變異的「晶圓變異與可擴充性」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for wafer variability and scaling in across-dot variability?","options":["比較跨假想元件參數分佈而非只取最佳點。","CMOS 相容即表示所有位元均已容錯。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Compare assumed device distributions rather than one best point.","CMOS compatibility means all qubits are already fault-tolerant.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"製程相容性支援多顆元件，但均勻性、接線及校正依然限制擴充。 比較跨假想元件參數分佈而非只取最佳點。","explanationEn":"Process compatibility supports many devices while uniformity, wiring and calibration still limit scaling. Compare assumed device distributions rather than one best point."}},{"id":"v11-intel-tunnel-falls-v11-11","order":3,"sequence":11,"title":"低溫電子與能耗：架構分析","titleEn":"Cryogenic electronics and energy: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-10"],"objective":"針對低溫控制熱預算提出可反駁的低溫電子與能耗模型與驗證紀錄。","objectiveEn":"Produce a falsifiable cryogenic electronics and energy model and evidence record for cryogenic-controller heat budget.","instruction":"在「Intel Tunnel Falls 矽自旋研究晶片」的師傅示意與公開來源中，先辨識低溫控制熱預算。近端電子降低接線需求但增加局部發熱；需要按低溫層分配功耗。 建立低溫電子與能耗的輸入、狀態、輸出及邊界圖；本課重點是量子點、交換、自旋讀出與晶圓變異。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。把控制功耗與每層散熱裕度分開。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify cryogenic-controller heat budget in the mentor diagram and primary sources for Intel Tunnel Falls silicon-spin research chip. Local electronics reduce wiring but add heat, requiring temperature-stage power budgets. Draw the inputs, states, outputs and boundaries of cryogenic electronics and energy, focusing on quantum dots, exchange, spin readout and wafer variability. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate controller power from cooling margins per stage. Record units, undisclosed parameters and model breakdown conditions.","observation":"把控制功耗與每層散熱裕度分開。","observationEn":"Separate controller power from cooling margins per stage.","failure":"常見誤判：把控制器移到低溫可忽略其發熱。","failureEn":"Common misconception: Moving controllers cold eliminates their heat.","check":"提交低溫控制熱預算的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for cryogenic-controller heat budget.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-11-k1","title":"低溫電子與能耗","titleEn":"Cryogenic electronics and energy","text":"近端電子降低接線需求但增加局部發熱；需要按低溫層分配功耗。 本課架構對應：低溫控制熱預算","textEn":"Local electronics reduce wiring but add heat, requiring temperature-stage power budgets. Course architecture correspondence: Cryogenic-controller heat budget","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"把控制功耗與每層散熱裕度分開。 應逐項保留基準與不確定度；把控制器移到低溫可忽略其發熱。 是本單元要排除的誤解。","textEn":"Separate controller power from cooling margins per stage. Retain each reference and uncertainty; reject the misconception: Moving controllers cold eliminates their heat.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 57 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^57=0.939193。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 57 independent events with equal p=0.0011: no-error probability (1−p)^57=0.939193. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就低溫控制熱預算的「低溫電子與能耗」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for cryogenic electronics and energy in cryogenic-controller heat budget?","options":["把控制器移到低溫可忽略其發熱。","近端電子降低接線需求但增加局部發熱；需要按低溫層分配功耗。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Moving controllers cold eliminates their heat.","Local electronics reduce wiring but add heat, requiring temperature-stage power budgets.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"近端電子降低接線需求但增加局部發熱；需要按低溫層分配功耗。 把控制功耗與每層散熱裕度分開。","explanationEn":"Local electronics reduce wiring but add heat, requiring temperature-stage power budgets. Separate controller power from cooling margins per stage."}},{"id":"v11-intel-tunnel-falls-v11-12","order":4,"sequence":12,"title":"低溫電子與能耗：證據驗證","titleEn":"Cryogenic electronics and energy: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"prerequisiteIds":["v11-intel-tunnel-falls-v11-11"],"objective":"針對低溫控制熱預算提出可反駁的低溫電子與能耗模型與驗證紀錄。","objectiveEn":"Produce a falsifiable cryogenic electronics and energy model and evidence record for cryogenic-controller heat budget.","instruction":"沿用前一步「低溫電子與能耗」模型，檢查低溫控制熱預算的兩個假想案例。把控制功耗與每層散熱裕度分開。 先訂可接受誤差，再比較預測與獨立計算；區分近端電子降低接線需求但增加局部發熱；需要按低溫層分配功耗。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous cryogenic electronics and energy model to inspect two hypothetical cases involving cryogenic-controller heat budget. Separate controller power from cooling margins per stage. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Local electronics reduce wiring but add heat, requiring temperature-stage power budgets.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"把控制功耗與每層散熱裕度分開。","observationEn":"Separate controller power from cooling margins per stage.","failure":"常見誤判：把控制器移到低溫可忽略其發熱。","failureEn":"Common misconception: Moving controllers cold eliminates their heat.","check":"提交低溫控制熱預算的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for cryogenic-controller heat budget.","knowledge":[{"id":"v11-intel-tunnel-falls-v11-12-k1","title":"低溫電子與能耗","titleEn":"Cryogenic electronics and energy","text":"近端電子降低接線需求但增加局部發熱；需要按低溫層分配功耗。 本課架構對應：低溫控制熱預算","textEn":"Local electronics reduce wiring but add heat, requiring temperature-stage power budgets. Course architecture correspondence: Cryogenic-controller heat budget","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"把控制功耗與每層散熱裕度分開。 應逐項保留基準與不確定度；把控制器移到低溫可忽略其發熱。 是本單元要排除的誤解。","textEn":"Separate controller power from cooling margins per stage. Retain each reference and uncertainty; reject the misconception: Moving controllers cold eliminates their heat.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"]},{"id":"v11-intel-tunnel-falls-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 57 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^57=0.939193。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 57 independent events with equal p=0.0011: no-error probability (1−p)^57=0.939193. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-tunnelfalls","v11x-qbasic"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就低溫控制熱預算的「低溫電子與能耗」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for cryogenic electronics and energy in cryogenic-controller heat budget?","options":["把控制器移到低溫可忽略其發熱。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","把控制功耗與每層散熱裕度分開。"],"optionsEn":["Moving controllers cold eliminates their heat.","Equal case averages rule out spatial, temporal and model errors.","Separate controller power from cooling margins per stage."],"answer":2,"explanation":"近端電子降低接線需求但增加局部發熱；需要按低溫層分配功耗。 把控制功耗與每層散熱裕度分開。","explanationEn":"Local electronics reduce wiring but add heat, requiring temperature-stage power budgets. Separate controller power from cooling margins per stage."}}]}],"summary":"以量子點、交換、自旋讀出與晶圓變異解析Intel Tunnel Falls 矽自旋研究晶片：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore Intel Tunnel Falls silicon-spin research chip through quantum dots, exchange, spin readout and wafer variability: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","scope":"依公開研究與裝置資料編寫的離線模型、編譯及證據判讀。不是實機組裝、雷射或低溫作業SOP；假想算例不代表廠商精度、量子優勢或容錯能力。研發宣稱與已驗證觀測分開標示。","scopeEn":"Offline models, compilation and evidence interpretation from public research/device sources. Not hardware assembly, laser/cryogenic SOPs; assumed examples are not vendor fidelity, advantage or fault tolerance. Development claims and demonstrated observations remain distinct.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"假設 57 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^57=0.939193。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 57 independent events with equal p=0.0011: no-error probability (1−p)^57=0.939193. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"network","labels":["閘定義量子點","鄰點交換","自旋共振選擇","自旋轉電荷讀出","跨點參數變異","低溫控制熱預算"],"labelsEn":["Gate-defined dots","Neighbor exchange","Spin-resonance selectivity","Spin-to-charge readout","Across-dot variability","Cryogenic-controller heat budget"],"original":true,"notToScale":true},"vendorHints":[{"name":"Intel","nameEn":"Intel","url":"https://www.intel.com/content/www/us/en/newsroom/news/quantum-computing-chip-to-advance-research.html","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-tunnelfalls"]},{"name":"IBM","nameEn":"IBM","url":"https://quantum.cloud.ibm.com/learning/en/courses/basics-of-quantum-information","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-qbasic"]}],"architectureNodes":[["電壓與共振控制","Voltage/resonance control"],["矽量子點","Silicon quantum dots"],["電荷感測器","Charge sensors"],["經典控制器","Classical controller"],["低溫支援","Cryogenic support"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,0],[4,1]],"architectureFamily":"qpu","educationEdition":11,"enrichmentVersion":11}};
